-- South Korea deep-dive ES/DE/FR translations (completing 283). INSERT OR IGNORE.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Reporte en tiempo real posterior a la emisión — el sistema e-Tax Invoice del Servicio Nacional de Impuestos (NTS)', 'Esta página de análisis refleja la orientación pública del Servicio Nacional de Impuestos y las noticias del sector disponibles en agosto de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. El umbral para empresarios individuales se ha reducido repetidamente y se esperan más reducciones — confirme la cifra actual directamente con el NTS o con su asesor fiscal antes de basarse en cualquier número concreto.', 'El sistema e-Tax Invoice de Corea del Sur es el mandato más maduro de este seguimiento: obligatorio para todas las corporaciones desde enero de 2011, y luego extendido a los empresarios individuales mediante un umbral de ingresos que ha bajado por etapas desde entonces — 1.000 millones de KRW (2012) → 300 millones (2014) → 200 millones (2022) → 100 millones (2023, junto con la introducción de las facturas de autofacturación) → 80 millones (2024), el más bajo hasta la fecha.', 'Las facturas e-Tax Invoice se crean en formato XML con una firma digital — ya sea un certificado de una Autoridad de Certificación Pública o un certificado electrónico fiscal emitido por el NTS — y se transmiten a la Plataforma Central del NTS (Hometax).', 'A diferencia de los mandatos de modelo de validación habituales en otras partes de este seguimiento, Corea del Sur opera un modelo de reporte en tiempo real posterior a la emisión: la factura es legalmente válida una vez entregada al comprador, y la transmisión al NTS al día siguiente es una obligación de reporte independiente, no una condición previa para su validez. El mandato cubre las transacciones B2B y B2G nacionales; no existe un requisito general de facturación electrónica B2C.', 'Cumplir implica confirmar si está dentro del ámbito de aplicación (todas las corporaciones, o los empresarios individuales por encima del umbral actual de 80 millones de KRW), obtener un certificado digital, elegir un canal de envío, y cumplir con el plazo de transmisión al día siguiente.', 'Corea del Sur respalda el mandato con un régimen sancionador graduado, calculado como porcentaje del valor de suministro, para las corporaciones y los empresarios individuales dentro del ámbito de aplicación, con un tope anual salvo para las infracciones intencionadas — y, por separado, las facturas de proveedores ausentes o incorrectas hacen que el comprador pierda sus propios derechos de deducción del IVA soportado.', 'El sistema e-Tax Invoice de Corea del Sur ha exigido la facturación electrónica del IVA y el reporte al NTS al día siguiente para todas las corporaciones desde enero de 2011 — el mandato de mayor duración de todo este seguimiento. Los empresarios individuales se han ido incorporando mediante un umbral de ingresos en constante descenso, ahora en 80 millones de KRW desde julio de 2024, el nivel más bajo hasta la fecha. Las sanciones se gradúan según el tipo de infracción (2% del valor de suministro por no emisión, hasta 0,3%-0,5% por transmisión tardía) y, por separado, las facturas no conformes le cuestan al comprador su propia deducción del IVA.', '🇰🇷' FROM countries WHERE name_en = 'South Korea';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Meldung nach Rechnungsausstellung in Echtzeit — das e-Tax-Invoice-System der nationalen Steuerbehörde (NTS)', 'Diese Analyseseite spiegelt öffentlich verfügbare Hinweise der nationalen Steuerbehörde und Branchenberichte mit Stand August 2026 wider und dient der allgemeinen Information, nicht der Rechts- oder Steuerberatung. Der Schwellenwert für Einzelunternehmer wurde wiederholt gesenkt, und weitere Senkungen werden allgemein erwartet — bestätigen Sie die aktuelle Zahl direkt bei der NTS oder Ihrem Steuerberater, bevor Sie sich auf eine bestimmte Zahl verlassen.', 'Südkoreas e-Tax-Invoice-System ist die ausgereifteste Pflicht in diesem Tracker: verpflichtend für alle Kapitalgesellschaften seit Januar 2011, dann auf Einzelunternehmer ausgeweitet über einen Umsatzschwellenwert, der seither in Stufen gesunken ist — 1 Milliarde KRW (2012) → 300 Millionen (2014) → 200 Millionen (2022) → 100 Millionen (2023, zusammen mit der Einführung der Selbstfakturierung) → 80 Millionen (2024), der bisher niedrigste Wert.', 'e-Tax Invoices werden im XML-Format mit einer digitalen Signatur erstellt — entweder einem Zertifikat einer öffentlichen Zertifizierungsstelle oder einem von der NTS ausgestellten E-Steuerzertifikat — und an die zentrale NTS-Plattform (Hometax) übermittelt.', 'Anders als bei den andernorts in diesem Tracker verbreiteten Freigabemodell-Pflichten betreibt Südkorea ein Meldemodell nach Rechnungsausstellung in Echtzeit: Die Rechnung ist rechtsgültig, sobald sie dem Käufer zugestellt wurde, und die Übermittlung an die NTS am nächsten Tag ist eine gesonderte Meldepflicht, keine Voraussetzung für die Gültigkeit. Die Pflicht erfasst inländische B2B- und B2G-Transaktionen; eine allgemeine B2C-Pflicht zur elektronischen Rechnungsstellung besteht nicht.', 'Um konform zu sein, müssen Sie prüfen, ob Sie betroffen sind (alle Kapitalgesellschaften, oder Einzelunternehmer oberhalb des aktuellen Schwellenwerts von 80 Millionen KRW), ein digitales Zertifikat beschaffen, einen Übermittlungskanal wählen und die Übermittlungsfrist bis zum nächsten Werktag einhalten.', 'Südkorea untermauert die Pflicht mit einem gestuften, am Lieferwert bemessenen Bußgeldkatalog für Kapitalgesellschaften und betroffene Einzelunternehmer, gedeckelt pro Jahr außer bei vorsätzlichen Verstößen — und gesondert führen fehlende oder fehlerhafte Lieferantenrechnungen dazu, dass der Käufer seinen eigenen Vorsteuerabzug verliert.', 'Südkoreas e-Tax-Invoice-System verlangt seit Januar 2011 die elektronische Mehrwertsteuerrechnungsstellung und die Meldung an die NTS am nächsten Tag für alle Kapitalgesellschaften — die am längsten laufende Pflicht in diesem gesamten Tracker. Einzelunternehmer wurden über einen stetig sinkenden Umsatzschwellenwert einbezogen, aktuell 80 Millionen KRW seit Juli 2024, das bisher niedrigste Niveau. Die Sanktionen sind nach Verstoßart gestuft (2% des Lieferwerts bei Nichtausstellung, bis 0,3%-0,5% bei verspäteter Übermittlung), und gesondert kosten nicht konforme Rechnungen den Käufer den eigenen Vorsteuerabzug.', '🇰🇷' FROM countries WHERE name_en = 'South Korea';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Déclaration en temps réel postérieure à l''émission — le système e-Tax Invoice de l''Administration fiscale nationale (NTS)', 'Cette page d''analyse reflète les directives publiques de l''Administration fiscale nationale et les informations sectorielles disponibles en août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Le seuil pour les entrepreneurs individuels a été réduit à plusieurs reprises et de nouvelles réductions sont largement attendues — confirmez le chiffre actuel directement auprès de la NTS ou de votre conseiller fiscal avant de vous fier à un chiffre précis.', 'Le système e-Tax Invoice de la Corée du Sud est l''obligation la plus mature de ce suivi : obligatoire pour toutes les sociétés depuis janvier 2011, puis étendu aux entrepreneurs individuels via un seuil de revenu qui a baissé par étapes depuis lors — 1 milliard de KRW (2012) → 300 millions (2014) → 200 millions (2022) → 100 millions (2023, avec l''introduction de l''autofacturation) → 80 millions (2024), le plus bas à ce jour.', 'Les factures e-Tax Invoice sont créées au format XML avec une signature numérique — soit un certificat d''une autorité de certification publique, soit un certificat fiscal électronique délivré par la NTS — et transmises à la plateforme centrale de la NTS (Hometax).', 'Contrairement aux obligations à modèle de validation courantes ailleurs dans ce suivi, la Corée du Sud applique un modèle de déclaration en temps réel postérieure à l''émission : la facture est juridiquement valide dès sa remise à l''acheteur, et la transmission à la NTS le lendemain constitue une obligation déclarative distincte, non une condition préalable à sa validité. L''obligation couvre les transactions B2B et B2G nationales ; il n''existe pas d''exigence générale de facturation électronique B2C.', 'Se mettre en conformité implique de vérifier si vous êtes concerné (toutes les sociétés, ou les entrepreneurs individuels au-delà du seuil actuel de 80 millions de KRW), d''obtenir un certificat numérique, de choisir un canal de soumission, et de respecter le délai de transmission au jour ouvré suivant.', 'La Corée du Sud appuie l''obligation sur un barème de sanctions gradué, calculé en pourcentage de la valeur de fourniture, pour les sociétés et les entrepreneurs individuels concernés, plafonné annuellement sauf pour les infractions intentionnelles — et, séparément, les factures fournisseurs manquantes ou incorrectes font perdre à l''acheteur ses propres droits de déduction de la TVA en amont.', 'Le système e-Tax Invoice de la Corée du Sud exige la facturation électronique de la TVA et la déclaration à la NTS le lendemain pour toutes les sociétés depuis janvier 2011 — l''obligation la plus ancienne couverte par ce suivi. Les entrepreneurs individuels ont été progressivement intégrés via un seuil de revenu en baisse constante, désormais à 80 millions de KRW depuis juillet 2024, le niveau le plus bas à ce jour. Les sanctions sont graduées selon le type d''infraction (2% de la valeur de fourniture pour non-émission, jusqu''à 0,3%-0,5% pour transmission tardive), et séparément, les factures non conformes coûtent à l''acheteur sa propre déduction de TVA.', '🇰🇷' FROM countries WHERE name_en = 'South Korea';

