INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Formato de factura", "XML, con firma digital"], ["Opciones de firma digital", "Certificado de una Autoridad de Certificación Pública, o un certificado electrónico fiscal emitido por el NTS"], ["Plataforma de transmisión", "Plataforma Central del NTS (Hometax)"], ["Base legal", "Ley del Impuesto al Valor Agregado, administrada por el Servicio Nacional de Impuestos"]]', 'El patrón de XML más firma digital lleva más de una década estable, por lo que la mayoría de los sistemas contables y ERP ya lo admiten de forma nativa — la decisión de integración real es qué canal de envío usar entre los cinco disponibles.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Rechnungsformat", "XML, mit digitaler Signatur"], ["Optionen für die digitale Signatur", "Zertifikat einer öffentlichen Zertifizierungsstelle, oder ein von der NTS ausgestelltes E-Steuerzertifikat"], ["Übermittlungsplattform", "Zentrale NTS-Plattform (Hometax)"], ["Rechtsgrundlage", "Mehrwertsteuergesetz, verwaltet von der nationalen Steuerbehörde"]]', 'Das Muster aus XML plus digitaler Signatur ist seit über einem Jahrzehnt stabil, sodass die meisten Buchhaltungs- und ERP-Systeme es bereits nativ unterstützen — die eigentliche Integrationsentscheidung betrifft, welchen der fünf Übermittlungskanäle Sie nutzen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Format de facture", "XML, avec signature numérique"], ["Options de signature numérique", "Certificat d''une autorité de certification publique, ou un certificat fiscal électronique délivré par la NTS"], ["Plateforme de transmission", "Plateforme centrale de la NTS (Hometax)"], ["Base légale", "Loi sur la taxe sur la valeur ajoutée, administrée par l''Administration fiscale nationale"]]', 'Le schéma XML plus signature numérique est stable depuis plus d''une décennie, si bien que la plupart des systèmes comptables et ERP le prennent déjà en charge nativement — la véritable décision d''intégration porte sur lequel des cinq canaux de soumission utiliser.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'file_format' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores y registro', '[["Identidad del contribuyente", "Número de registro empresarial coreano"], ["Canales de envío", "Portal gratuito NTS Hometax, un ASP certificado, un sistema contable interno con certificado digital, el sistema telefónico AVRS, o en persona en una oficina tributaria"], ["Plataforma de registro/reporte", "hometax.go.kr"], ["Autoridad", "Servicio Nacional de Impuestos (NTS)"]]', 'Cinco canales distintos es más de lo que ofrecen la mayoría de los mandatos de este seguimiento — las vías telefónica AVRS y presencial existen específicamente para los contribuyentes muy pequeños sin infraestructura digital propia.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kennungen & Registrierung', '[["Steuerzahleridentität", "Koreanische Gewerberegistrierungsnummer"], ["Übermittlungskanäle", "Kostenloses NTS-Hometax-Portal, ein zertifizierter ASP, ein internes Buchhaltungssystem mit digitalem Zertifikat, das AVRS-Telefonsystem, oder persönlich bei einem Finanzamt"], ["Registrierungs-/Meldeplattform", "hometax.go.kr"], ["Behörde", "Nationale Steuerbehörde (NTS)"]]', 'Fünf getrennte Kanäle sind mehr, als die meisten Pflichten in diesem Tracker bieten — die AVRS-Telefon- und die persönliche Variante existieren speziell für sehr kleine Steuerzahler ohne eigene digitale Infrastruktur.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants et enregistrement', '[["Identité du contribuable", "Numéro d''immatriculation d''entreprise coréen"], ["Canaux de soumission", "Portail gratuit NTS Hometax, un ASP certifié, un système comptable interne avec certificat numérique, le système téléphonique AVRS, ou en personne dans un bureau des impôts"], ["Plateforme d''enregistrement/de déclaration", "hometax.go.kr"], ["Autorité", "Administration fiscale nationale (NTS)"]]', 'Cinq canaux distincts, c''est plus que ce qu''offrent la plupart des obligations de ce suivi — les voies téléphonique AVRS et en personne existent spécifiquement pour les très petits contribuables sans infrastructure numérique propre.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'file_format' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio y archivo', '[["Campos requeridos", "Número de identificación fiscal y dirección de ambas partes, coste con IVA incluido, fecha de la factura, información del cliente"], ["Campo opcional", "La descripción de los bienes no es obligatoria"], ["Periodo de conservación", "5 años; el almacenamiento centralizado del NTS ya cumple esta obligación sin necesidad de un archivo propio del proveedor"], ["Autofacturación", "Disponible desde julio de 2023 cuando un proveedor no puede emitir una factura, sujeto a confirmación de una oficina tributaria de distrito"]]', 'Que el propio almacenamiento centralizado del gobierno cubra el requisito de conservación es una comodidad real que la mayoría de los mandatos más recientes de este seguimiento todavía no ofrecen — una cosa menos que gestionar para una empresa que cumple.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalt & Archivierung', '[["Erforderliche Felder", "Steueridentifikationsnummer und Adresse beider Parteien, Kosten inklusive Mehrwertsteuer, Rechnungsdatum, Kundendaten"], ["Optionales Feld", "Die Warenbeschreibung ist nicht verpflichtend"], ["Aufbewahrungsfrist", "5 Jahre; die zentrale NTS-Speicherung erfüllt diese Pflicht mittlerweile ohne ein separates Lieferantenarchiv"], ["Selbstfakturierung", "Seit Juli 2023 verfügbar, wenn ein Lieferant keine Rechnung ausstellen kann, vorbehaltlich der Bestätigung durch ein Bezirksfinanzamt"]]', 'Dass die eigene zentrale Speicherung der Regierung die Aufbewahrungspflicht abdeckt, ist ein echter Komfort, den die meisten neueren Pflichten in diesem Tracker noch nicht bieten — eine Sache weniger, die ein konformes Unternehmen selbst verwalten muss.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire et archivage', '[["Champs requis", "Numéro d''identification fiscale et adresse des deux parties, coût TVA incluse, date de la facture, informations client"], ["Champ facultatif", "La description des biens n''est pas obligatoire"], ["Durée de conservation", "5 ans ; le stockage centralisé de la NTS satisfait désormais cette obligation sans archive propre du fournisseur"], ["Autofacturation", "Disponible depuis juillet 2023 lorsqu''un fournisseur ne peut pas émettre de facture, sous réserve de confirmation par un bureau des impôts de district"]]', 'Le fait que le stockage centralisé du gouvernement lui-même couvre l''obligation de conservation est un confort réel que la plupart des obligations plus récentes de ce suivi n''offrent pas encore — une chose de moins à gérer pour une entreprise en conformité.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'file_format' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo de emisión y reporte', 'Toda factura e-Tax Invoice pasa por la misma secuencia — note que esto es reporte, no validación:', 'La factura ya es legalmente válida en cuanto llega al comprador — no se solicita al NTS que la apruebe primero. Esta es la diferencia clave frente a los mandatos de modelo de validación cubiertos en otras partes de este seguimiento.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'South Korea' AND lc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der Ablauf: erst ausstellen, dann melden', 'Jede e-Tax Invoice durchläuft dieselbe Abfolge — beachten Sie, dass dies eine Meldung ist, kein Freigabemodell:', 'Die Rechnung ist bereits rechtsgültig, sobald sie den Käufer erreicht — die NTS wird nicht vorab um Genehmigung gebeten. Das ist der entscheidende Unterschied zu den andernorts in diesem Tracker behandelten Freigabemodell-Pflichten.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'South Korea' AND lc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le flux émission puis déclaration', 'Chaque facture e-Tax Invoice suit la même séquence — notez qu''il s''agit d''une déclaration, pas d''une validation :', 'La facture est déjà juridiquement valide dès qu''elle atteint l''acheteur — il n''est pas demandé à la NTS de l''approuver au préalable. C''est la différence clé avec les obligations à modèle de validation traitées ailleurs dans ce suivi.' FROM deep_dive_lifecycle_cards lc JOIN countries c ON c.id = lc.country_id WHERE c.name_en = 'South Korea' AND lc.sort_order = 0;

