INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Quién está dentro del ámbito, y desde cuándo', '[["Todas las corporaciones", "Obligatorio desde enero de 2011, sin importar el tamaño"], ["Empresarios individuales por encima de 80 millones de KRW", "Obligatorio desde julio de 2024 (el umbral ha bajado por etapas desde 2012)"], ["Empresarios individuales por debajo del umbral", "Solo participación voluntaria"], ["Transacciones B2B y B2G nacionales", "La cobertura real del mandato — vea la siguiente tarjeta para lo que queda excluido"]]', 'El umbral ha bajado cinco veces desde 2012 (1.000 millones → 300 millones → 200 millones → 100 millones → 80 millones de KRW) — compruebe la cifra actual directamente en lugar de confiar en un número que pudo haber visto hace unos años.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Wer betroffen ist, und seit wann', '[["Alle Kapitalgesellschaften", "Verpflichtend seit Januar 2011, unabhängig von der Größe"], ["Einzelunternehmer über 80 Millionen KRW", "Verpflichtend seit Juli 2024 (der Schwellenwert ist seit 2012 stufenweise gesunken)"], ["Einzelunternehmer unterhalb des Schwellenwerts", "Nur freiwillige Teilnahme"], ["Inländische B2B- und B2G-Transaktionen", "Die tatsächliche Reichweite der Pflicht — was ausgenommen ist, siehe die nächste Karte"]]', 'Der Schwellenwert ist seit 2012 fünfmal gesunken (1 Milliarde → 300 Millionen → 200 Millionen → 100 Millionen → 80 Millionen KRW) — prüfen Sie die aktuelle Zahl direkt, statt sich auf eine Zahl zu verlassen, die Sie vielleicht vor einigen Jahren gesehen haben.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Qui est concerné, et depuis quand', '[["Toutes les sociétés", "Obligatoire depuis janvier 2011, quelle que soit la taille"], ["Entrepreneurs individuels au-delà de 80 millions de KRW", "Obligatoire depuis juillet 2024 (le seuil a baissé par étapes depuis 2012)"], ["Entrepreneurs individuels sous le seuil", "Participation volontaire uniquement"], ["Transactions B2B et B2G nationales", "La couverture réelle de l''obligation — voir la carte suivante pour ce qui est exclu"]]', 'Le seuil a baissé cinq fois depuis 2012 (1 milliard → 300 millions → 200 millions → 100 millions → 80 millions de KRW) — vérifiez le chiffre actuel directement plutôt que de vous fier à un chiffre que vous avez pu voir il y a quelques années.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Solo B2B y B2G nacional', '[["B2B", "Cubierto — el núcleo del mandato"], ["B2G", "Cubierto"], ["B2C (venta minorista al consumidor)", "No cubierto por el mandato e-Tax Invoice"], ["Transacciones transfronterizas/de exportación", "No abordadas por este mandato"]]', 'Este es un alcance más reducido que varios mandatos de otras partes de este seguimiento que también llegan al B2C — vale la pena comprobarlo frente a su propia combinación de transacciones antes de asumir una cobertura completa.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Nur inländisches B2B und B2G', '[["B2B", "Erfasst — der Kern der Pflicht"], ["B2G", "Erfasst"], ["B2C (Verbraucher-Einzelhandel)", "Von der e-Tax-Invoice-Pflicht nicht erfasst"], ["Grenzüberschreitende/Export-Transaktionen", "Von dieser Pflicht nicht behandelt"]]', 'Dies ist ein engerer Anwendungsbereich als bei mehreren Pflichten andernorts in diesem Tracker, die auch B2C erfassen — es lohnt sich, dies mit Ihrer eigenen Transaktionsmischung abzugleichen, bevor Sie von einer vollständigen Abdeckung ausgehen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Uniquement B2B et B2G national', '[["B2B", "Couvert — le cœur de l''obligation"], ["B2G", "Couvert"], ["B2C (vente au détail aux consommateurs)", "Non couvert par l''obligation e-Tax Invoice"], ["Transactions transfrontalières/d''exportation", "Non traitées par cette obligation"]]', 'Il s''agit d''un champ d''application plus restreint que plusieurs obligations ailleurs dans ce suivi qui couvrent aussi le B2C — cela vaut la peine de le comparer à votre propre répartition des transactions avant de supposer une couverture complète.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

