INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🧾 Denegación de la deducción del IVA — una segunda consecuencia independiente', NULL, NULL, 'Además de las multas anteriores, una e-Tax Invoice ausente o incorrecta hace que el comprador pierda sus propios derechos de deducción del IVA soportado en esa transacción. Al igual que en varios otros mandatos de este seguimiento, esto da a todo comprador registrado a efectos del IVA un incentivo financiero directo para vigilar el cumplimiento de sus proveedores, no solo a la autoridad tributaria.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🧾 Verweigerung des Vorsteuerabzugs — eine zweite, gesonderte Folge', NULL, NULL, 'Über die oben genannten Bußgelder hinaus führt eine fehlende oder fehlerhafte e-Tax Invoice dazu, dass der Käufer seinen eigenen Vorsteuerabzug für diese Transaktion verliert. Wie bei mehreren anderen Pflichten in diesem Tracker gibt dies jedem umsatzsteuerregistrierten Käufer einen direkten finanziellen Anreiz, die Einhaltung durch seine Lieferanten zu überwachen — nicht nur der Steuerbehörde.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🧾 Refus de déduction de la TVA — une seconde conséquence distincte', NULL, NULL, 'Au-delà des amendes ci-dessus, une e-Tax Invoice manquante ou incorrecte fait perdre à l''acheteur ses propres droits de déduction de la TVA en amont sur cette transaction. Comme pour plusieurs autres obligations de ce suivi, cela donne à tout acheteur assujetti à la TVA une incitation financière directe à surveiller la conformité de ses fournisseurs, pas seulement à l''administration fiscale.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'penalties_related' AND dc.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📅 Quince años de aplicación, no un riesgo nuevo', NULL, NULL, 'A diferencia de la mayoría de los mandatos añadidos a este seguimiento, el sistema e-Tax Invoice de Corea del Sur no es un cambio reciente que haya que planificar — se aplica a todas las corporaciones desde 2011. La cuestión de cumplimiento vigente para la mayoría de las empresas hoy es solo si el umbral actual de 80 millones de KRW para empresarios individuales les aplica, no si el propio sistema es nuevo.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📅 Fünfzehn Jahre Durchsetzung, kein neues Risiko', NULL, NULL, 'Anders als bei den meisten Pflichten, die diesem Tracker hinzugefügt wurden, ist Südkoreas e-Tax-Invoice-System keine kürzliche Änderung, auf die man sich einstellen müsste — es gilt seit 2011 für alle Kapitalgesellschaften. Die aktuell relevante Compliance-Frage für die meisten Unternehmen ist heute nur, ob der aktuelle Schwellenwert von 80 Millionen KRW für Einzelunternehmer auf sie zutrifft, nicht ob das System selbst neu ist.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📅 Quinze ans d''application, pas un risque nouveau', NULL, NULL, 'Contrairement à la plupart des obligations ajoutées à ce suivi, le système e-Tax Invoice de la Corée du Sud n''est pas un changement récent à anticiper — il s''applique à toutes les sociétés depuis 2011. La question de conformité actuelle pour la plupart des entreprises aujourd''hui est simplement de savoir si le seuil actuel de 80 millions de KRW pour les entrepreneurs individuels s''applique à elles, pas si le système lui-même est nouveau.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'penalties_related' AND dc.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚖️ Las sanciones por facturas ficticias se endurecen en 2026', NULL, NULL, 'Por separado del baremo sancionador de e-Tax Invoice anterior, el régimen sancionador de IVA más amplio de Corea del Sur se está endureciendo: la multa por emitir o recibir una factura de IVA ficticia sube del 3% al 4% del importe de suministro imponible indicado, dentro de un conjunto más amplio de cambios en la legislación fiscal coreana de 2026 — un recordatorio de que incluso un mandato maduro y asentado como este sigue generando noticias regulatorias reales.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚖️ Sanktionen für fingierte Rechnungen verschärfen sich 2026', NULL, NULL, 'Getrennt vom oben genannten e-Tax-Invoice-Bußgeldkatalog wird Südkoreas breiteres Mehrwertsteuer-Sanktionsregime strenger: Das Bußgeld für die Ausstellung oder den Erhalt einer fingierten Mehrwertsteuerrechnung steigt von 3% auf 4% des ausgewiesenen steuerpflichtigen Lieferbetrags, Teil eines umfassenderen Pakets koreanischer Steuerrechtsänderungen für 2026 — eine Erinnerung daran, dass selbst eine ausgereifte, etablierte Pflicht wie diese weiterhin echte regulatorische Nachrichten hervorbringt.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚖️ Les sanctions pour factures fictives se durcissent en 2026', NULL, NULL, 'Séparément du barème de sanctions e-Tax Invoice ci-dessus, le régime de sanctions TVA plus large de la Corée du Sud se durcit : l''amende pour émission ou réception d''une facture de TVA fictive passe de 3% à 4% du montant de fourniture imposable indiqué, dans le cadre d''un ensemble plus large de changements de la législation fiscale coréenne pour 2026 — un rappel que même une obligation mature et bien établie comme celle-ci continue de générer une véritable actualité réglementaire.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'South Korea' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme si está dentro del ámbito de aplicación', 'Todas las corporaciones están dentro del ámbito desde 2011 sin importar su tamaño; los empresarios individuales deben comparar su valor de suministro del año anterior con el umbral actual de 80 millones de KRW, no con una cifra más antigua.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie, ob Sie betroffen sind', 'Alle Kapitalgesellschaften sind seit 2011 unabhängig von der Größe betroffen; Einzelunternehmer sollten ihren Vorjahresumsatz mit dem aktuellen Schwellenwert von 80 Millionen KRW vergleichen, nicht mit einer älteren Zahl.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez si vous êtes concerné', 'Toutes les sociétés sont concernées depuis 2011 quelle que soit leur taille ; les entrepreneurs individuels doivent comparer leur valeur de fourniture de l''année précédente au seuil actuel de 80 millions de KRW, et non à un chiffre plus ancien.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 0;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Obtenga un certificado digital', 'Necesitará un certificado de una Autoridad de Certificación Pública o un certificado electrónico fiscal emitido por el NTS antes de poder emitir una e-Tax Invoice conforme.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beschaffen Sie ein digitales Zertifikat', 'Sie benötigen entweder ein Zertifikat einer öffentlichen Zertifizierungsstelle oder ein von der NTS ausgestelltes E-Steuerzertifikat, bevor Sie eine konforme e-Tax Invoice ausstellen können.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Obtenez un certificat numérique', 'Vous aurez besoin d''un certificat d''une autorité de certification publique ou d''un certificat fiscal électronique délivré par la NTS avant de pouvoir émettre une e-Tax Invoice conforme.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija su canal de envío', 'Elija entre el portal gratuito NTS Hometax, un ASP certificado, un sistema contable interno con certificado digital, el sistema telefónico AVRS, o la presentación en persona — el que mejor se adapte a su volumen de facturación y sistemas existentes.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie Ihren Übermittlungskanal', 'Wählen Sie zwischen dem kostenlosen NTS-Hometax-Portal, einem zertifizierten ASP, einem internen Buchhaltungssystem mit digitalem Zertifikat, dem AVRS-Telefonsystem, oder der persönlichen Einreichung — je nachdem, was zu Ihrem Rechnungsvolumen und Ihren vorhandenen Systemen passt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez votre canal de soumission', 'Choisissez parmi le portail gratuit NTS Hometax, un ASP certifié, un système comptable interne avec certificat numérique, le système téléphonique AVRS, ou le dépôt en personne — celui qui correspond le mieux à votre volume de facturation et à vos systèmes existants.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Adapte el contenido de su factura a los campos requeridos', 'Cubra el número de identificación fiscal y la dirección de ambas partes, el coste con IVA incluido, la fecha de la factura y la información del cliente — la descripción de los bienes es opcional.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bilden Sie Ihre Rechnungsinhalte auf die erforderlichen Felder ab', 'Decken Sie die Steueridentifikationsnummer und Adresse beider Parteien, die Kosten inklusive Mehrwertsteuer, das Rechnungsdatum und die Kundendaten ab — die Warenbeschreibung ist optional.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Adaptez le contenu de votre facture aux champs requis', 'Couvrez le numéro d''identification fiscale et l''adresse des deux parties, le coût TVA incluse, la date de la facture et les informations client — la description des biens est facultative.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Cumpla el plazo de transmisión del día hábil siguiente', 'Transmita al NTS antes del día siguiente a la emisión cuando sea posible; existe el resumen mensual como alternativa antes del día 10 del mes siguiente, pero conlleva su propio riesgo de sanción si se usa de forma habitual.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Halten Sie die Übermittlungsfrist bis zum nächsten Werktag ein', 'Übermitteln Sie nach Möglichkeit bis zum Tag nach der Ausstellung an die NTS; die monatliche Sammelmeldung bis zum 10. des Folgemonats existiert als Rückfalloption, birgt aber bei regelmäßiger Nutzung ein eigenes Bußgeldrisiko.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Respectez le délai de transmission du jour ouvré suivant', 'Transmettez à la NTS au plus tard le lendemain de l''émission si possible ; la synthèse mensuelle de secours avant le 10 du mois suivant existe mais comporte son propre risque de sanction si elle est utilisée régulièrement.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Audite las facturas entrantes antes de reclamar la deducción del IVA soportado', 'Una e-Tax Invoice de un proveedor ausente o incorrecta bloquea su propia deducción, sin importar de quién sea la culpa — compruébelo antes de basarse en ella.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie eingehende Rechnungen, bevor Sie den Vorsteuerabzug geltend machen', 'Eine fehlende oder fehlerhafte e-Tax Invoice eines Lieferanten blockiert Ihren eigenen Abzug, unabhängig davon, wessen Fehler es ist — prüfen Sie dies, bevor Sie sich darauf verlassen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez les factures entrantes avant de réclamer la déduction de la TVA en amont', 'Une e-Tax Invoice manquante ou incorrecte d''un fournisseur bloque votre propre déduction, quelle que soit la responsabilité — vérifiez avant de vous y fier.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'South Korea' AND ds.sort_order = 5;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'NTS Hometax — sistema e-Tax Invoice' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'South Korea' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'NTS Hometax — e-Tax-Invoice-System' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'South Korea' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'NTS Hometax — système e-Tax Invoice' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'South Korea' AND dp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'Servicio Nacional de Impuestos (NTS) — portal de información en inglés' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'South Korea' AND dp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'Nationale Steuerbehörde (NTS) — englischsprachiges Informationsportal' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'South Korea' AND dp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'Administration fiscale nationale (NTS) — portail d''information en anglais' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'South Korea' AND dp.sort_order = 1;
